package ncasa.expense.application.plan;
import java.time.LocalDate;import java.util.UUID;import ncasa.expense.application.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;
public final class ListExpensePlansUseCase{private final ExpensePlanRepository plans;private final HouseholdExpenseAccessPort access;public ListExpensePlansUseCase(ExpensePlanRepository p,HouseholdExpenseAccessPort a){plans=p;access=a;}public ExpensePlanPage execute(Long actor,UUID householdId,ExpensePlanStatus status,UUID payer,UUID participant,ExpensePlanFrequency frequency,LocalDate from,LocalDate to,int page,int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");if(from!=null&&to!=null&&from.isAfter(to))throw new IllegalArgumentException("Invalid occurrence range");var h=new HouseholdRef(householdId);var c=access.getContext(h,actor);MemberRef p=payer==null?null:new MemberRef(payer),part=participant==null?null:new MemberRef(participant);if(p!=null)c.requireMember(p);if(part!=null)c.requireMember(part);var result=plans.findPage(h,status,p,part,frequency,from,to,page,size);return new ExpensePlanPage(result.content().stream().map(ExpensePlanView::from).toList(),page,size,result.totalElements(),(int)Math.ceil((double)result.totalElements()/size));}}
